def get_website_content(url):
    try:
        response = requests.get(url)
        return response.text
    except:
        return None

def find_script(url):
    content = get_website_content(url)
    if content is None:
        return None
    script = re.search(r'script\s*src\s*=\s*["\'](.*)["\']', content)
    if script:
        return script

